"""Mobilepose framework parameters conversion module."""

import torch

from nn_models.tensorflow_keras.object_detection.fcos import FCOS

# dimensions order when converting PyTorch to TensorFlow
PT2TF_CONV = (2, 3, 1, 0) # convolution

def convert_pytorch_into_keras(pytorch_input_file: str, keras_output_file: str, model_args):
    """Converts `FCOS` parameters file from PyTorch to Keras."""

    # Keras model instantiation
    model = FCOS(*model_args)
    # load PyTorch parameters
    params = torch.load(pytorch_input_file, map_location="cpu")
    # copy PyTorch parameters to Keras model
    model.get_layer("conv1").set_weights([params["resnet.layer0.conv.weight"].permute(PT2TF_CONV).numpy()])
    model.get_layer("bn1").set_weights([params["resnet.layer0.bn.weight"].numpy(),
                                        params["resnet.layer0.bn.bias"].numpy(),
                                        params["resnet.layer0.bn.running_mean"].numpy(),
                                        params["resnet.layer0.bn.running_var"].numpy()])
    model.get_layer("conv2_1_conv1").set_weights([params["resnet.layer1.conv2_1.conv1.weight"].permute(PT2TF_CONV).numpy()])
    model.get_layer("conv2_1_bn1").set_weights([params["resnet.layer1.conv2_1.bn1.weight"].numpy(),
                                                params["resnet.layer1.conv2_1.bn1.bias"].numpy(),
                                                params["resnet.layer1.conv2_1.bn1.running_mean"].numpy(),
                                                params["resnet.layer1.conv2_1.bn1.running_var"].numpy()])
